                        calendar.calendar_id,
                        resource.event_id,
                        crate::event::AllDayOccurrenceChange {
                            recurrence_date: date.format("%Y-%m-%d").to_string(),
                            expected_version: event.version,
                            event: mutation,
                        },
                    )
                    .await
                {
                    Ok(projection) => projection,
                    Err(EventServiceError::Conflict { .. }) => {
                        return (StatusCode::PRECONDITION_FAILED, "precondition failed").into_response();
                    }
                    Err(EventServiceError::NotFound) => return dav_resource_not_found(),
                    Err(EventServiceError::ReadOnly) => return dav_resource_not_found(),
                    Err(_) => return dav_server_error(),
                }
            }
        }
    } else {
        let result = if is_existing_recurring {
            let mut changes = Vec::with_capacity(exceptions.len() + incoming.exdates.len());
            for exception in &exceptions {
                let exception_timing = match &exception.timing {
                    crate::ics::NormalizedTiming::Timed { starts_at, ends_at, timezone } => EventTiming::Timed {
                        start_utc: starts_at.timestamp(), end_utc: ends_at.timestamp(),
                        timezone: timezone.clone().unwrap_or_else(|| "UTC".to_owned()),
                    },
                    crate::ics::NormalizedTiming::AllDay { start_date, end_date } => EventTiming::AllDay {
                        start_date: start_date.format("%Y-%m-%d").to_string(), end_date: end_date.format("%Y-%m-%d").to_string(),
                    },
                };
                let exception_event = EventMutation {
                    title: exception.summary.clone(), description: exception.description.clone(), location: exception.location.clone(),
                    status: match exception.status.as_deref() { Some("TENTATIVE") => EventStatus::Tentative, Some("CANCELLED") => EventStatus::Cancelled, _ => EventStatus::Confirmed },
                    timing: exception_timing,
                };
                match exception.recurrence_id.as_ref().expect("filtered above") {
                    crate::ics::NormalizedDateValue::Timed(dt) => changes.push(RecurringExceptionChange::UpdateTimed(OccurrenceChange { recurrence_id: dt.timestamp(), expected_version: 0, event: exception_event })),
                    crate::ics::NormalizedDateValue::AllDay(date) => changes.push(RecurringExceptionChange::UpdateAllDay(AllDayOccurrenceChange { recurrence_date: date.format("%Y-%m-%d").to_string(), expected_version: 0, event: exception_event })),
                }
            }
            for exdate in &incoming.exdates {
                changes.push(match exdate {
                    crate::ics::NormalizedDateValue::Timed(dt) => RecurringExceptionChange::DeleteTimed(dt.timestamp()),
                    crate::ics::NormalizedDateValue::AllDay(date) => RecurringExceptionChange::DeleteAllDay(date.format("%Y-%m-%d").to_string()),
                });
            }
            applied_recurring_exceptions = true;
            event_service.replace_recurring_series(session.user_id, false, calendar.calendar_id, resource.event_id, RecurringSeriesChange { expected_version: event.version, event: mutation, exceptions: changes }).await
        } else {
            event_service.update(session.user_id, false, calendar.calendar_id, resource.event_id, EventChange { expected_version: event.version, target_calendar_id: calendar.calendar_id, event: mutation }).await
        };
