              WHERE calendar_acl.user_id = ?
                AND calendars.archived = 0
              ORDER BY calendars.id",
        )
        .bind(user_id)
        .fetch_all(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(rows
            .into_iter()
            .map(
                |(
                    calendar_id,
                    owner_user_id,
                    owner_principal_id,
                    name,
                    description,
                    color,
                    role,
                )| CaldavCalendar {
                    calendar_id,
                    owner_user_id,
                    owner_principal_id,
                    name,
                    description,
                    color,
                    role,
                },
            )
            .collect())
    }

