use std::fmt::{self, Display, Formatter};

use chrono::{NaiveDate, NaiveDateTime, TimeZone, Utc};
use quick_xml::Reader;
use quick_xml::events::Event;

pub const MAX_BODY_BYTES: usize = 64 * 1024;
pub const MAX_RESULTS: usize = 1000;
pub const MAX_RANGE_SECONDS: i64 = 366 * 24 * 60 * 60;
pub const MAX_MULTIGET_HREFS: usize = 1000;

#[derive(Debug, PartialEq, Eq)]
pub enum QueryError {
    MalformedXml,
    UnsupportedRoot,
    MissingFilter,
    UnsupportedFilter,
    InvalidDateTime,
    InvalidRange,
    RangeTooLarge,
    MissingHref,
    TooManyHrefs,
    BadSyncLevel,
}

impl Display for QueryError {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        match self {
            Self::MalformedXml => write!(f, "malformed XML"),
            Self::UnsupportedRoot => write!(f, "unsupported report type"),
            Self::MissingFilter => write!(f, "missing filter"),
            Self::UnsupportedFilter => write!(f, "unsupported filter"),
            Self::InvalidDateTime => write!(f, "invalid date-time value"),
            Self::InvalidRange => write!(f, "invalid time range"),
            Self::RangeTooLarge => write!(f, "time range too large"),
            Self::MissingHref => write!(f, "missing href"),
            Self::TooManyHrefs => write!(f, "too many hrefs"),
            Self::BadSyncLevel => write!(f, "sync-level must be 1"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CalendarQuery {
    pub start_utc: i64,
    pub end_utc: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CalendarMultiget {
    pub hrefs: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncCollection {
    /// Opaque token from the client; `None` (or empty) requests an initial
    /// snapshot.
    pub sync_token: Option<String>,
    /// `sync-level` must be 1 for calendar sync; other values are rejected.
    pub sync_level: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CalendarReport {
    Query(CalendarQuery),
    Multiget(CalendarMultiget),
    SyncCollection(SyncCollection),
}

fn local_name(tag: &str) -> &str {
    match tag.rsplit_once(':') {
        Some((_, name)) => name,
        None => tag,
    }
}

fn parse_ical_datetime(value: &str) -> Result<i64, QueryError> {
    let value = value.trim();
    if value.is_empty() {
        return Err(QueryError::InvalidDateTime);
    }
    if value.ends_with('Z') || value.ends_with('z') {
        let naive = parse_ical_naive(&value[..value.len() - 1])?;
        Ok(Utc.from_utc_datetime(&naive).timestamp())
    } else if value.len() == 8 {
        let date =
            NaiveDate::parse_from_str(value, "%Y%m%d").map_err(|_| QueryError::InvalidDateTime)?;
        Ok(Utc
            .from_utc_datetime(
                &date
                    .and_hms_opt(0, 0, 0)
                    .ok_or(QueryError::InvalidDateTime)?,
            )
            .timestamp())
    } else {
        Err(QueryError::InvalidDateTime)
    }
}

fn parse_ical_naive(value: &str) -> Result<NaiveDateTime, QueryError> {
    if value.len() != 15 {
        return Err(QueryError::InvalidDateTime);
    }
    let naive = NaiveDateTime::parse_from_str(value, "%Y%m%dT%H%M%S")
        .map_err(|_| QueryError::InvalidDateTime)?;
    Ok(naive)
}

fn name_to_str(name: &[u8]) -> &str {
    std::str::from_utf8(name).unwrap_or("")
}

pub fn parse_calendar_query(body: &[u8]) -> Result<CalendarQuery, QueryError> {
    if body.len() > MAX_BODY_BYTES {
        return Err(QueryError::MalformedXml);
    }
    let text = std::str::from_utf8(body).map_err(|_| QueryError::MalformedXml)?;
    let mut reader = Reader::from_str(text);
    reader.config_mut().trim_text(true);

    let mut buf = Vec::new();
    let mut root_seen = false;
    let mut in_filter = false;
    let mut filter_depth: u32 = 0;
    let mut found_time_range = false;
    let mut start_utc: Option<i64> = None;
    let mut end_utc: Option<i64> = None;
    let mut unsupported_in_filter = false;
    let mut depth: u32 = 0;

    fn extract_time_range(
        attrs: quick_xml::events::attributes::Attributes,
    ) -> Result<(Option<i64>, Option<i64>), QueryError> {
        let mut s: Option<i64> = None;
        let mut e: Option<i64> = None;
        for attr_result in attrs {
            let Ok(attr) = attr_result else {
                return Err(QueryError::MalformedXml);
            };
            let key = name_to_str(attr.key.as_ref());
            let k = local_name(key);
            let val = attr
                .unescape_value()
                .map(|v| v.into_owned())
                .unwrap_or_default();
            if k == "start" {
                s = Some(parse_ical_datetime(&val)?);
            } else if k == "end" {
                e = Some(parse_ical_datetime(&val)?);
            }
        }
        Ok((s, e))
    }

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref start)) => {
                let local_name_ref = start.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "calendar-query" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    depth = 1;
                    continue;
                }
                depth += 1;
                if in_filter {
                    filter_depth += 1;
                    if local == "time-range" {
                        found_time_range = true;
                        let (s, e) = extract_time_range(start.attributes())?;
                        start_utc = start_utc.or(s);
                        end_utc = end_utc.or(e);
                    } else if local != "filter" {
                        unsupported_in_filter = true;
                    }
                } else if local == "filter" {
                    in_filter = true;
                    filter_depth = 1;
                }
            }
            Ok(Event::Empty(ref empty)) => {
                let local_name_ref = empty.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "calendar-query" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    continue;
                }
                if in_filter {
                    if local == "time-range" {
                        found_time_range = true;
                        let (s, e) = extract_time_range(empty.attributes())?;
                        start_utc = start_utc.or(s);
                        end_utc = end_utc.or(e);
                    } else if local != "filter" {
                        unsupported_in_filter = true;
                    }
                }
            }
            Ok(Event::End(_)) => {
                depth = depth.saturating_sub(1);
                if in_filter {
                    filter_depth = filter_depth.saturating_sub(1);
                    if filter_depth == 0 {
                        in_filter = false;
                    }
                }
            }
            Ok(Event::Eof) => {
                if depth > 0 {
                    return Err(QueryError::MalformedXml);
                }
                break;
            }
            Ok(_) => {}
            Err(_) => return Err(QueryError::MalformedXml),
        }
        buf.clear();
    }

    if !root_seen {
        return Err(QueryError::UnsupportedRoot);
    }
    if unsupported_in_filter {
        return Err(QueryError::UnsupportedFilter);
    }
    if !found_time_range {
        return Err(QueryError::MissingFilter);
    }
    let start = start_utc.ok_or(QueryError::InvalidDateTime)?;
    let end = end_utc.ok_or(QueryError::InvalidDateTime)?;
    if start >= end {
        return Err(QueryError::InvalidRange);
    }
    if end - start > MAX_RANGE_SECONDS {
        return Err(QueryError::RangeTooLarge);
    }
    Ok(CalendarQuery {
        start_utc: start,
        end_utc: end,
    })
}

/// Parse a `calendar-multiget` REPORT body into its requested hrefs.
///
/// Only `<D:href>` elements that are direct children of the root are
/// captured. The list is bounded by `MAX_MULTIGET_HREFS`.
pub fn parse_calendar_multiget(body: &[u8]) -> Result<CalendarMultiget, QueryError> {
    if body.len() > MAX_BODY_BYTES {
        return Err(QueryError::MalformedXml);
    }
    let text = std::str::from_utf8(body).map_err(|_| QueryError::MalformedXml)?;
    let mut reader = Reader::from_str(text);
    reader.config_mut().trim_text(true);

    let mut buf = Vec::new();
    let mut root_seen = false;
    let mut depth: u32 = 0;
    let mut hrefs: Vec<String> = Vec::new();
    let mut capturing_href = false;
    let mut current_href = String::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref start)) => {
                let local_name_ref = start.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "calendar-multiget" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    depth = 1;
                    continue;
                }
                depth += 1;
                if depth == 2 && local == "href" {
                    capturing_href = true;
                    current_href.clear();
                }
            }
            Ok(Event::Empty(ref empty)) => {
                let local_name_ref = empty.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "calendar-multiget" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    continue;
                }
                depth += 1;
                if depth == 2 && local == "href" {
                    // Self-closing href carries no text; record it as empty.
                    if hrefs.len() >= MAX_MULTIGET_HREFS {
                        return Err(QueryError::TooManyHrefs);
                    }
                    hrefs.push(String::new());
                }
                depth = depth.saturating_sub(1);
            }
            Ok(Event::Text(ref text_event)) => {
                if capturing_href {
                    current_href.push_str(text_event.unescape().unwrap_or_default().as_ref());
                }
            }
            Ok(Event::End(_)) => {
                if capturing_href {
                    capturing_href = false;
                    if hrefs.len() >= MAX_MULTIGET_HREFS {
                        return Err(QueryError::TooManyHrefs);
                    }
                    hrefs.push(current_href.trim().to_owned());
                }
                depth = depth.saturating_sub(1);
            }
            Ok(Event::Eof) => {
                if depth > 0 {
                    return Err(QueryError::MalformedXml);
                }
                break;
            }
            Ok(_) => {}
            Err(_) => return Err(QueryError::MalformedXml),
        }
        buf.clear();
    }

    if !root_seen {
        return Err(QueryError::UnsupportedRoot);
    }
    if hrefs.is_empty() {
        return Err(QueryError::MissingHref);
    }
    Ok(CalendarMultiget { hrefs })
}

/// Parse a `sync-collection` REPORT body into its sync token and level.
///
/// The `sync-token` element is optional: an absent or empty token requests an
/// initial snapshot. The `sync-level` element must be present and equal to 1
/// for calendar sync; any other value is rejected.
pub fn parse_sync_collection(body: &[u8]) -> Result<SyncCollection, QueryError> {
    if body.len() > MAX_BODY_BYTES {
        return Err(QueryError::MalformedXml);
    }
    let text = std::str::from_utf8(body).map_err(|_| QueryError::MalformedXml)?;
    let mut reader = Reader::from_str(text);
    reader.config_mut().trim_text(true);

    let mut buf = Vec::new();
    let mut root_seen = false;
    let mut depth: u32 = 0;
    let mut sync_token: Option<String> = None;
    let mut sync_level: Option<u32> = None;
    let mut capturing: Option<&'static str> = None;
    let mut current = String::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref start)) => {
                let local_name_ref = start.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "sync-collection" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    depth = 1;
                    continue;
                }
                depth += 1;
                if depth == 2 {
                    if local == "sync-token" {
                        capturing = Some("token");
                        current.clear();
                    } else if local == "sync-level" {
                        capturing = Some("level");
                        current.clear();
                    }
                }
            }
            Ok(Event::Empty(ref empty)) => {
                let local_name_ref = empty.local_name();
                let local = name_to_str(local_name_ref.as_ref());
                if !root_seen {
                    if local != "sync-collection" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_seen = true;
                    continue;
                }
                depth += 1;
                if depth == 2 && local == "sync-token" {
                    // Self-closing sync-token carries no text: initial snapshot.
                    sync_token = Some(String::new());
                }
                depth = depth.saturating_sub(1);
            }
            Ok(Event::Text(ref text_event)) => {
                if capturing.is_some() {
                    current.push_str(text_event.unescape().unwrap_or_default().as_ref());
                }
            }
            Ok(Event::End(_)) => {
                if let Some(kind) = capturing {
                    capturing = None;
                    let value = current.trim().to_owned();
                    match kind {
                        "token" => {
                            sync_token = Some(value);
                        }
                        "level" => {
                            sync_level = value.parse::<u32>().ok();
                        }
                        _ => {}
                    }
                }
                depth = depth.saturating_sub(1);
            }
            Ok(Event::Eof) => {
                if depth > 0 {
                    return Err(QueryError::MalformedXml);
                }
                break;
            }
            Ok(_) => {}
            Err(_) => return Err(QueryError::MalformedXml),
        }
        buf.clear();
    }

    if !root_seen {
        return Err(QueryError::UnsupportedRoot);
    }
    let level = sync_level.ok_or(QueryError::BadSyncLevel)?;
    if level != 1 {
        return Err(QueryError::BadSyncLevel);
    }
    let token = sync_token.unwrap_or_default();
    Ok(SyncCollection {
        sync_token: if token.is_empty() { None } else { Some(token) },
        sync_level: level,
    })
}

/// Determine the report type from the body and parse it accordingly.
pub fn parse_calendar_report(body: &[u8]) -> Result<CalendarReport, QueryError> {
    if body.len() > MAX_BODY_BYTES {
        return Err(QueryError::MalformedXml);
    }
    let text = std::str::from_utf8(body).map_err(|_| QueryError::MalformedXml)?;
    let root = peek_root(text).ok_or(QueryError::UnsupportedRoot)?;
    match root.as_str() {
        "calendar-query" => Ok(CalendarReport::Query(parse_calendar_query(body)?)),
        "calendar-multiget" => Ok(CalendarReport::Multiget(parse_calendar_multiget(body)?)),
        "sync-collection" => Ok(CalendarReport::SyncCollection(parse_sync_collection(body)?)),
        _ => Err(QueryError::UnsupportedRoot),
    }
}

/// Read the first element name in an XML document, if any.
fn peek_root(text: &str) -> Option<String> {
    let mut reader = Reader::from_str(text);
    reader.config_mut().trim_text(true);
    let mut buf = Vec::new();
    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref start)) => {
                return Some(name_to_str(start.local_name().as_ref()).to_owned());
            }
            Ok(Event::Empty(ref empty)) => {
                return Some(name_to_str(empty.local_name().as_ref()).to_owned());
            }
            Ok(Event::Eof) => return None,
            Ok(_) => {}
            Err(_) => return None,
        }
        buf.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid_query() -> String {
        r#"<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
  <D:prop>
    <D:getetag/>
    <D:getcontenttype/>
    <C:calendar-data/>
  </D:prop>
  <C:filter>
    <C:time-range start="20260101T000000Z" end="20260131T235959Z"/>
  </C:filter>
</C:calendar-query>"#
            .to_owned()
    }

    fn valid_multiget() -> String {
        r#"<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
  <D:prop>
    <D:getetag/>
    <D:getcontenttype/>
    <C:calendar-data/>
  </D:prop>
  <D:href>/dav/calendars/p/1/aaa.ics</D:href>
  <D:href>/dav/calendars/p/1/bbb.ics</D:href>
</C:calendar-multiget>"#
            .to_owned()
    }

    #[test]
    fn parses_valid_multiget_hrefs() {
        let m = parse_calendar_multiget(valid_multiget().as_bytes()).unwrap();
        assert_eq!(
            m.hrefs,
            vec![
                "/dav/calendars/p/1/aaa.ics".to_owned(),
                "/dav/calendars/p/1/bbb.ics".to_owned()
            ]
        );
    }

    #[test]
    fn parses_multiget_single_href() {
        let body = r#"<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:href>/dav/calendars/p/1/aaa.ics</D:href></C:calendar-multiget>"#;
        let m = parse_calendar_multiget(body.as_bytes()).unwrap();
        assert_eq!(m.hrefs, vec!["/dav/calendars/p/1/aaa.ics".to_owned()]);
    }

    #[test]
    fn rejects_multiget_missing_href() {
        let body = r#"<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:prop><D:getetag/></D:prop></C:calendar-multiget>"#;
        assert_eq!(
            parse_calendar_multiget(body.as_bytes()).unwrap_err(),
            QueryError::MissingHref
        );
    }

    #[test]
    fn rejects_multiget_wrong_root() {
        let body = r#"<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:href>/x/</D:href></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_multiget(body.as_bytes()).unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn rejects_multiget_malformed_xml() {
        let body = r#"<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:href>"#;
        assert_eq!(
            parse_calendar_multiget(body.as_bytes()).unwrap_err(),
            QueryError::MalformedXml
        );
    }

    #[test]
    fn rejects_multiget_too_many_hrefs() {
        let hrefs = (0..=MAX_MULTIGET_HREFS)
            .map(|i| format!("<D:href>/dav/calendars/p/1/{i}.ics</D:href>"))
            .collect::<Vec<_>>()
            .join("");
        let body = format!(
            r#"<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">{hrefs}</C:calendar-multiget>"#
        );
        assert_eq!(
            parse_calendar_multiget(body.as_bytes()).unwrap_err(),
            QueryError::TooManyHrefs
        );
    }

    #[test]
    fn accepts_multiget_at_href_limit() {
        let hrefs = (0..MAX_MULTIGET_HREFS)
            .map(|i| format!("<D:href>/dav/calendars/p/1/{i}.ics</D:href>"))
            .collect::<Vec<_>>()
            .join("");
        let body = format!(
            r#"<C:calendar-multiget xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">{hrefs}</C:calendar-multiget>"#
        );
        let m = parse_calendar_multiget(body.as_bytes()).unwrap();
        assert_eq!(m.hrefs.len(), MAX_MULTIGET_HREFS);
    }

    #[test]
    fn report_dispatches_calendar_query() {
        let report = parse_calendar_report(valid_query().as_bytes()).unwrap();
        assert!(matches!(report, CalendarReport::Query(_)));
    }

    #[test]
    fn report_dispatches_calendar_multiget() {
        let report = parse_calendar_report(valid_multiget().as_bytes()).unwrap();
        match report {
            CalendarReport::Multiget(m) => assert_eq!(m.hrefs.len(), 2),
            _ => panic!("expected multiget"),
        }
    }

    #[test]
    fn report_rejects_unknown_root() {
        let body = r#"<C:unknown-report xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:href>/x/</D:href></C:unknown-report>"#;
        assert_eq!(
            parse_calendar_report(body.as_bytes()).unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn report_dispatches_sync_collection() {
        let body = r#"<C:sync-collection xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:sync-token></D:sync-token><D:sync-level>1</D:sync-level><D:prop><D:getetag/></D:prop></C:sync-collection>"#;
        let report = parse_calendar_report(body.as_bytes()).unwrap();
        match report {
            CalendarReport::SyncCollection(sync) => {
                assert!(sync.sync_token.is_none());
                assert_eq!(sync.sync_level, 1);
            }
            _ => panic!("expected sync-collection"),
        }
    }

    #[test]
    fn sync_collection_parses_token_and_level() {
        let body = r#"<C:sync-collection xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:sync-token>opaque-token-123</D:sync-token><D:sync-level>1</D:sync-level></C:sync-collection>"#;
        let sync = parse_sync_collection(body.as_bytes()).unwrap();
        assert_eq!(sync.sync_token.as_deref(), Some("opaque-token-123"));
        assert_eq!(sync.sync_level, 1);
    }

    #[test]
    fn sync_collection_rejects_bad_level() {
        let body = r#"<C:sync-collection xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:sync-token></D:sync-token><D:sync-level>2</D:sync-level></C:sync-collection>"#;
        assert_eq!(
            parse_sync_collection(body.as_bytes()).unwrap_err(),
            QueryError::BadSyncLevel
        );
    }

    #[test]
    fn sync_collection_rejects_missing_level() {
        let body = r#"<C:sync-collection xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:sync-token></D:sync-token></C:sync-collection>"#;
        assert_eq!(
            parse_sync_collection(body.as_bytes()).unwrap_err(),
            QueryError::BadSyncLevel
        );
    }

    #[test]
    fn sync_collection_rejects_wrong_root() {
        let body = r#"<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:sync-token></D:sync-token><D:sync-level>1</D:sync-level></C:calendar-query>"#;
        assert_eq!(
            parse_sync_collection(body.as_bytes()).unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn parses_valid_time_range() {
        let q = parse_calendar_query(valid_query().as_bytes()).unwrap();
        assert_eq!(q.start_utc, 1767225600);
        assert_eq!(q.end_utc, 1769903999);
    }

    #[test]
    fn rejects_empty_body() {
        assert_eq!(
            parse_calendar_query(b"").unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn rejects_non_xml() {
        assert_eq!(
            parse_calendar_query(b"not xml at all").unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn rejects_wrong_root_element() {
        let body = r#"<C:calendar-multiget xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:href xmlns:D="DAV:">/x/</D:href></C:calendar-multiget>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::UnsupportedRoot
        );
    }

    #[test]
    fn rejects_missing_filter() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><D:prop xmlns:D="DAV:"><D:getetag/></D:prop></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::MissingFilter
        );
    }

    #[test]
    fn rejects_unsupported_filter_type() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:comp-filter name="VEVENT"><C:prop-filter name="SUMMARY"><C:is-text matches="anywhere">test</C:is-text></C:prop-filter></C:comp-filter></C:filter></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::UnsupportedFilter
        );
    }

    #[test]
    fn rejects_invalid_start_before_end() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:time-range start="20260131T000000Z" end="20260101T000000Z"/></C:filter></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::InvalidRange
        );
    }

    #[test]
    fn rejects_equal_start_and_end() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:time-range start="20260101T000000Z" end="20260101T000000Z"/></C:filter></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::InvalidRange
        );
    }

    #[test]
    fn rejects_range_too_large() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:time-range start="20200101T000000Z" end="20260101T000000Z"/></C:filter></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::RangeTooLarge
        );
    }

    #[test]
    fn rejects_invalid_date_format() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:time-range start="notadate" end="20260101T000000Z"/></C:filter></C:calendar-query>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::InvalidDateTime
        );
    }

    #[test]
    fn rejects_oversized_body() {
        let mut body = valid_query();
        body.push_str(&format!("<!-- {} -->", "x".repeat(MAX_BODY_BYTES)));
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::MalformedXml
        );
    }

    #[test]
    fn accepts_date_only_start() {
        let body = r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter><C:time-range start="20260101" end="20260131T235959Z"/></C:filter></C:calendar-query>"#;
        let q = parse_calendar_query(body.as_bytes()).unwrap();
        assert_eq!(q.start_utc, 1767225600);
    }

    #[test]
    fn rejects_malformed_xml() {
        let body =
            r#"<C:calendar-query xmlns:C="urn:ietf:params:xml:ns:calendarserver/"><C:filter>"#;
        assert_eq!(
            parse_calendar_query(body.as_bytes()).unwrap_err(),
            QueryError::MalformedXml
        );
    }
}

use commoncal_backend::{
    admin::AdminService,
    admin_invitation_rate_limit::AdminInvitationRateLimiterState,
    backup::{Aes256GcmEncryptor, BackupCommand, BackupService, RestoreCommand, RestoreService},
    bootstrap::{BootstrapCommand, InitialSuperadminBootstrap},
    caldav::{
        auth::CaldavAccountService,
        http::{build_caldav_router, build_connection_management_router},
    },
    calendar::CalendarService,
    config::{AppConfig, Environment},
    database::{connect_and_migrate, connect_read_only},
    email::DevelopmentEmailSender,
    event::EventService,
    external_feed::ExternalFeedService,
    http::{
        Readiness, ResponseSecurityConfig,
        build_router_with_auth_flows_sessions_admin_calendars_views_and_external_feeds,
        secure_responses, serve_frontend,
    },
    invitations::InvitationConsumer,
    login::{FixedWindowLoginRateLimiter, LoginService},
    notification::NotificationWorker,
    public_rate_limit::PublicRateLimiterState,
    rate_limiter::FixedWindowRateLimiter,
    security::SecretKey,
    sessions::{SessionManager, SessionSecurityConfig},
    shared_view::SharedViewService,
    user_invitation::UserInvitationService,
    user_invitation_rate_limit::{
        USER_INVITATION_MAX_REQUESTS, USER_INVITATION_WINDOW_SECONDS,
        UserInvitationRateLimiterState,
    },
    write_rate_limit::WriteRateLimiterState,
};
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};
use tokio::net::TcpListener;
use tracing_subscriber::{EnvFilter, layer::SubscriberExt, util::SubscriberInitExt};
use url::Url;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    init_tracing();
    let config = AppConfig::from_env()?;
    let arguments: Vec<String> = std::env::args().skip(1).collect();
    if arguments.first().is_some_and(|value| value == "restore") {
        return run_restore(&config, &arguments[1..]).await;
    }
    if arguments.first().is_some_and(|value| value == "backup") {
        let database = connect_read_only(&config).await?;
        return run_backup(database, &arguments[1..]).await;
    }

    let readiness = Readiness::new();
    let database = connect_and_migrate(&config, readiness.clone()).await?;

    if arguments
        .first()
        .is_some_and(|value| value == "bootstrap-superadmin")
    {
        return run_bootstrap(&config, database, &arguments[1..]).await;
    }
    if arguments.first().is_some_and(|value| value == "seed") {
        return run_seed(&config, database).await;
    }
    if !arguments.is_empty() {
        return Err(format!("unknown command: {}", arguments[0]).into());
    }

    let listener = TcpListener::bind(config.bind_address).await?;

    tracing::info!(
        environment = ?config.environment,
        address = %config.bind_address,
        "server started"
    );

    let secret_key = config
        .session_secret()
        .map(|secret| SecretKey::derive(secret.as_bytes()))
        .unwrap_or_else(SecretKey::generate);
    let invitation_consumer =
        InvitationConsumer::new(database.clone(), secret_key.clone(), 30 * 24 * 60 * 60);
    let email_sender = Arc::new(DevelopmentEmailSender::new());
    let is_secure = config.app_origin().starts_with("https://");
    let login_service = LoginService::new(
        database.clone(),
        secret_key.clone(),
        15 * 60,
        30 * 24 * 60 * 60,
        "/login",
        email_sender.clone(),
        Arc::new(FixedWindowLoginRateLimiter::new(5, 15 * 60)),
        is_secure,
    );
    let session_manager = SessionManager::new(
        database.clone(),
        secret_key.clone(),
        SessionSecurityConfig::new(7 * 24 * 60 * 60, 5 * 60, config.app_origin())?,
    );
    let admin_service = AdminService::with_email_sender(
        database.clone(),
        secret_key.clone(),
        24 * 60 * 60,
        format!("{}/invitations/accept", config.app_origin()),
        email_sender.clone(),
    );
    let calendar_service = CalendarService::new(database.clone());
    let notification_service =
        commoncal_backend::notification::NotificationService::new(database.clone());
    let notification_worker_database = database.clone();
    let notification_worker_sender = email_sender.clone();
    tokio::spawn(async move {
        let mut tick = tokio::time::interval(std::time::Duration::from_secs(30));
        loop {
            tick.tick().await;
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .expect("system clock is before Unix epoch")
                .as_secs() as i64;
            let worker = NotificationWorker::new_at_with_email_sender(
                notification_worker_database.clone(),
                now,
                5 * 60,
                100,
                notification_worker_sender.clone(),
            );
            if worker.process_due().await.is_err() {
                tracing::error!(error_code = "notification_worker_failed");
            }
        }
    });
    let notification_replanner = notification_service.clone();
    let event_service = EventService::new_with_notification_replanner(
        database.clone(),
        Arc::new(move |event_id| {
            let notifications = notification_replanner.clone();
            tokio::spawn(async move {
                if notifications.replan_event(event_id).await.is_err() {
                    tracing::error!(error_code = "notification_replan_failed");
                }
            });
        }),
    );
    let external_feed_service = ExternalFeedService::new(database.clone(), secret_key.clone());
    let shared_view_service = SharedViewService::new_with_key(database.clone(), secret_key.clone());
    let caldav_public_origin = Url::parse(config.caldav_public_origin())
        .expect("CALDAV_PUBLIC_ORIGIN is validated as a well-formed origin");
    let caldav_accounts =
        CaldavAccountService::new(database.clone(), secret_key.clone(), caldav_public_origin);

    let write_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("development") {
        None
    } else {
        Some(WriteRateLimiterState {
            limiter: Arc::new(FixedWindowRateLimiter::new(30, 60)),
        })
    };

    let public_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("development") {
        None
    } else {
        Some(PublicRateLimiterState {
            limiter: Arc::new(FixedWindowRateLimiter::new(100, 60)),
        })
    };

    let admin_rate_limiter = if std::env::var("APP_ENV").ok().as_deref() == Some("production") {
        let limiter = FixedWindowRateLimiter::new(5, 60);
        Some(AdminInvitationRateLimiterState {
            limiter: Arc::new(limiter),
        })
    } else {
        None
    };

    let user_invitation_rate_limiter =
        if std::env::var("APP_ENV").ok().as_deref() == Some("production") {
            let limiter = FixedWindowRateLimiter::new(
                USER_INVITATION_MAX_REQUESTS,
                USER_INVITATION_WINDOW_SECONDS,
            );
            Some(UserInvitationRateLimiterState {
                limiter: Arc::new(limiter),
            })
        } else {
            None
        };

    let user_invitation_service = UserInvitationService::with_email_sender(
        database.clone(),
        secret_key.clone(),
        24 * 60 * 60,
        format!("{}/invitations/accept", config.app_origin()),
        email_sender.clone(),
    );
    let caldav_session_manager = session_manager.clone();

    let mut router = build_router_with_auth_flows_sessions_admin_calendars_views_and_external_feeds(
        readiness,
        invitation_consumer,
        login_service,
        session_manager,
        admin_service,
        calendar_service,
        event_service,
        shared_view_service,
        external_feed_service,
        notification_service,
        config.access_log_level(),
        is_secure,
        config.password_login_enabled(),
        write_rate_limiter,
        public_rate_limiter,
        admin_rate_limiter,
        user_invitation_service,
        user_invitation_rate_limiter,
    );

    // Add MCP internal API routes (separate router with its own state).
    // The internal API key is required in production; startup fails when it is
    // absent or empty so the boundary can never be left open.
    let mcp_internal_api_key = std::env::var("MCP_INTERNAL_API_KEY").unwrap_or_default();
    if config.environment == Environment::Production && mcp_internal_api_key.is_empty() {
        return Err("MCP_INTERNAL_API_KEY is required in production".into());
    }
    let mcp_router = commoncal_backend::mcp_internal::build_mcp_internal_router(
        database.clone(),
        commoncal_backend::mcp_internal::McpApiKeyAuth::new(mcp_internal_api_key),
    );
    router = router.merge(mcp_router);

    // Add McpGrant management routes (frontend-facing).
    let db_pool = database.clone();
    let mcp_grant_router = axum::Router::new()
        .route(
            "/api/v1/mcp-grants",
            axum::routing::get(commoncal_backend::mcp_grant_management::list_mcp_grants),
        )
        .route(
            "/api/v1/mcp-grants",
            axum::routing::post(commoncal_backend::mcp_grant_management::create_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id",
            axum::routing::patch(commoncal_backend::mcp_grant_management::update_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id",
            axum::routing::delete(commoncal_backend::mcp_grant_management::revoke_mcp_grant),
        )
        .route(
            "/api/v1/mcp-grants/:id/resend",
            axum::routing::post(
                commoncal_backend::mcp_grant_management::resend_mcp_grant_confirmation,
            ),
        )
        .with_state(db_pool);
    router = router.merge(mcp_grant_router);

    // Add CalDAV DAV router (isolated, Basic-auth, no browser session/CSRF).
    router = router.merge(build_caldav_router(caldav_accounts.clone()));
    // Add CalDAV connection-management browser API (cookie + CSRF protected).
    router = router.merge(build_connection_management_router(
        caldav_accounts,
        caldav_session_manager,
    ));

    let frontend_directory =
        std::env::var("FRONTEND_DIR").unwrap_or_else(|_| "/app/frontend".into());

    let response_security = if config.environment == Environment::Production
        && config.app_origin().starts_with("https://")
    {
        ResponseSecurityConfig::production_https()
    } else {
        ResponseSecurityConfig::local_http()
    };

    axum::serve(
        listener,
        secure_responses(
            serve_frontend(router, frontend_directory),
            response_security,
        )
        .into_make_service_with_connect_info::<SocketAddr>(),
    )
    .with_graceful_shutdown(shutdown_signal())
    .await?;

    Ok(())
}

async fn run_backup(
    database: sqlx::SqlitePool,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    let command = BackupCommand::from_arguments(arguments)?;
    let created_at = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;
    let encryption_key = std::env::var("BACKUP_ENCRYPTION_KEY_HEX")
        .map_err(|_| "BACKUP_ENCRYPTION_KEY_HEX is required for backup")?;
    let encryptor = Aes256GcmEncryptor::from_hex_key(&encryption_key)?;
    let metadata = BackupService::new(database)
        .create_encrypted_and_upload(command.destination_directory, created_at, &encryptor, None)
        .await?;
    println!("backup_id={}", metadata.id);
    println!("artifact_path={}", metadata.artifact_path.display());
    println!("snapshot_sha256={}", metadata.snapshot_sha256);
    println!("compressed_sha256={}", metadata.compressed_sha256);
    Ok(())
}

async fn run_restore(
    config: &AppConfig,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    let command = RestoreCommand::from_arguments(arguments)?;
    if config.environment == Environment::Production {
        command.refuse_production_target(config.database_path())?;
    }
    let encryption_key = std::env::var("BACKUP_ENCRYPTION_KEY_HEX")
        .map_err(|_| "BACKUP_ENCRYPTION_KEY_HEX is required for restore")?;
    let encryptor = Aes256GcmEncryptor::from_hex_key(&encryption_key)?;
    RestoreService::restore_encrypted(
        command.artifact_path,
        command.destination_database.clone(),
        &encryptor,
    )
    .await?;
    println!(
        "restored_database={}",
        command.destination_database.display()
    );
    Ok(())
}

async fn run_bootstrap(
    config: &AppConfig,
    database: sqlx::SqlitePool,
    arguments: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    if !(1..=2).contains(&arguments.len()) {
        return Err("usage: commoncal-backend bootstrap-superadmin <email> [display-name]".into());
    }
    let secret = config
        .session_secret()
        .filter(|value| !value.is_empty())
        .ok_or("SESSION_SECRET is required for bootstrap-superadmin")?;
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;
    let result = InitialSuperadminBootstrap::new(database, SecretKey::derive(secret.as_bytes()))
        .execute(BootstrapCommand {
            normalized_email: arguments[0].clone(),
            display_name: arguments.get(1).cloned(),
            created_at: now,
            expires_at: now + 24 * 60 * 60,
        })
        .await?;

    println!("invitation_id={}", result.invitation_id);
    println!("token={}", result.token.expose());
    Ok(())
}

async fn run_seed(
    config: &AppConfig,
    database: sqlx::SqlitePool,
) -> Result<(), Box<dyn std::error::Error>> {
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64;

    // Check if user already exists
    let mut tx = database.begin().await?;
    let user_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM users")
        .fetch_one(&mut *tx)
        .await?;

    if user_count > 0 {
        println!("database already has {} user(s), skipping seed", user_count);
        return Ok(());
    }

    // Allow seed in production only when DEFAULT_ADMIN_PASSWORD is set.
    if config.environment == Environment::Production
        && std::env::var("DEFAULT_ADMIN_PASSWORD")
            .ok()
            .filter(|v| !v.is_empty())
            .is_none()
    {
        return Err(
            "seed command is not allowed in production without DEFAULT_ADMIN_PASSWORD".into(),
        );
    }

    // Create user
    let user_id: i64 = sqlx::query_scalar(
        "INSERT INTO users (normalized_email, display_name, status, is_superadmin, created_at)
         VALUES ('dev@example.com', 'Dev User', 'active', 1, ?)
         RETURNING id",
    )
    .bind(now)
    .fetch_one(&database)
    .await?;

    // Optionally set password from DEFAULT_ADMIN_PASSWORD env var.
    if let Ok(password) = std::env::var("DEFAULT_ADMIN_PASSWORD")
        && !password.is_empty()
    {
        let hash = bcrypt::hash(&password, bcrypt::DEFAULT_COST)
            .map_err(|e| format!("bcrypt hash failed: {e}"))?;
        sqlx::query("UPDATE users SET password_hash = ? WHERE id = ?")
            .bind(&hash)
            .bind(user_id)
            .execute(&database)
            .await?;
        println!("  password:  set (from DEFAULT_ADMIN_PASSWORD)");
    }

    // Create calendar
    let calendar_id: i64 = sqlx::query_scalar(
        "INSERT INTO calendars (owner_user_id, name, color, default_timezone, default_event_visibility, created_at, updated_at)
         VALUES (?, 'My Calendar', '#3b82f6', 'UTC', 'default', ?, ?)
         RETURNING id",
    )
    .bind(user_id)
    .bind(now)
    .bind(now)
    .fetch_one(&database)
    .await?;

    // Create calendar_acl
    sqlx::query(
        "INSERT INTO calendar_acl (calendar_id, user_id, role, created_at, updated_at)
         VALUES (?, ?, 'owner', ?, ?)",
    )
    .bind(calendar_id)
    .bind(user_id)
    .bind(now)
    .bind(now)
    .execute(&database)
    .await?;

    println!("seeded:");
    println!("  email:     dev@example.com");
    println!("  display:   Dev User");
    println!("  superadmin: true");
    println!("  calendar:  My Calendar");

    Ok(())
}

fn init_tracing() {
    tracing_subscriber::registry()
        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .with(tracing_subscriber::fmt::layer().json())
        .init();
}

async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("failed to install SIGTERM handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        () = ctrl_c => {},
        () = terminate => {},
    }

    tracing::info!("shutdown signal received");
}

