/// Classifies DAV request outcomes for operator monitoring.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum CaldavFailureClass {
    AuthFailure,
    RateLimited,
    MalformedRequest,
    OversizedBody,
    Unauthorized,
    NotFound,
    PreconditionFailed,
    InternalError,
}

impl CaldavFailureClass {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::AuthFailure => "auth_failure",
            Self::RateLimited => "rate_limited",
            Self::MalformedRequest => "malformed_request",
            Self::OversizedBody => "oversized_body",
            Self::Unauthorized => "unauthorized",
            Self::NotFound => "not_found",
            Self::PreconditionFailed => "precondition_failed",
            Self::InternalError => "internal_error",
        }
    }
}

/// In-memory counter for DAV failure classifications.
///
/// Thread-safe via `AtomicU64`; suitable for periodic scraping by an
/// operator monitoring agent.
#[derive(Clone, Debug, Default)]
pub struct CaldavMetrics {
    auth_failures: std::sync::atomic::AtomicU64,
    rate_limited: std::sync::atomic::AtomicU64,
    malformed_requests: std::sync::atomic::AtomicU64,
    oversized_bodies: std::sync::atomic::AtomicU64,
    unauthorized: std::sync::atomic::AtomicU64,
    not_found: std::sync::atomic::AtomicU64,
    precondition_failed: std::sync::atomic::AtomicU64,
    internal_errors: std::sync::atomic::AtomicU64,
    successful_requests: std::sync::atomic::AtomicU64,
}

impl CaldavMetrics {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn record_auth_failure(&self) {
        self.auth_failures.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_rate_limited(&self) {
        self.rate_limited.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_malformed_request(&self) {
        self.malformed_requests.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_oversized_body(&self) {
        self.oversized_bodies.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_unauthorized(&self) {
        self.unauthorized.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_not_found(&self) {
        self.not_found.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_precondition_failed(&self) {
        self.precondition_failed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_internal_error(&self) {
        self.internal_errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn record_success(&self) {
        self.successful_requests.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    pub fn auth_failures(&self) -> u64 {
        self.auth_failures.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn rate_limited(&self) -> u64 {
        self.rate_limited.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn malformed_requests(&self) -> u64 {
        self.malformed_requests.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn oversized_bodies(&self) -> u64 {
        self.oversized_bodies.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn unauthorized(&self) -> u64 {
        self.unauthorized.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn not_found(&self) -> u64 {
        self.not_found.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn precondition_failed(&self) -> u64 {
        self.precondition_failed.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn internal_errors(&self) -> u64 {
        self.internal_errors.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn successful_requests(&self) -> u64 {
        self.successful_requests.load(std::sync::atomic::Ordering::Relaxed)
    }

    pub fn total_failures(&self) -> u64 {
        self.auth_failures()
            + self.rate_limited()
            + self.malformed_requests()
            + self.oversized_bodies()
            + self.unauthorized()
            + self.not_found()
            + self.precondition_failed()
            + self.internal_errors()
    }
}

#[derive(Debug)]
pub enum CaldavAuthError {
    InvalidCredentials,
    Revoked,
    RateLimited,
    Persistence,
    ResourceExists,
    UidConflict,
}

